import { Column, Entity, JoinColumn, ManyToOne, OneToMany, OneToOne, Index } from 'typeorm';
import { BaseEntity } from '../../../shared/entities/base-entity.entity';
import { User } from '../../user/entities/user.entity';
import { ActivityData } from '../domain/activity-data.model';
import { ActivityType } from '../domain/activity-type.enum';
import { LogSummaryType } from '../domain/log-summary-type.enum';
import { ActivitySequence } from './activity-sequence.entity';
import { CompletedActivity } from './completed-activity.entity';
import { ActivityTemplate } from '../../activity-template/entity/activity-template.entity';
import { DaysOfWeek } from '../domain/days-of-week.enum';
import { LogQuantityQuestion } from './log-quantity-questions';
import { ImpactCategory } from '../domain/impact-category.enum';
import { Tutorial } from './tutorial.entity';
import { Geofence } from '../../geofence/entities/geofence.entity';

@Entity('activities')
export class Activity extends BaseEntity {
  constructor({ id, log_summary_type, ...activity }: Partial<Activity> = {}, options = { generateId: false }) {
    super(id, options);
    Object.assign(this, { ...activity, log_summary_type: log_summary_type || LogSummaryType.SUM });
  }

  @Index()
  @Column({
    type: 'uuid',
    nullable: false,
  })
  user_id?: string;

  @Index()
  @Column({
    type: 'uuid',
  })
  parent_id?: string;

  @Column({
    type: 'uuid',
    nullable: true,
    default: null,
  })
  linked_activity_id?: string;

  @Index()
  @Column({
    type: 'uuid',
  })
  activity_template_id?: string;

  @Column({
    type: 'boolean',
    default: false,
  })
  has_choices?: boolean;

  @Index()
  @Column({
    type: 'uuid',
    nullable: false,
  })
  activity_sequence_id?: string;

  @Column({
    type: 'enum',
    name: 'activity_type',
    enum: ActivityType,
    nullable: false,
  })
  type?: ActivityType;

  @Column({
    type: 'enum',
    enum: LogSummaryType,
    default: LogSummaryType.SUM,
  })
  log_summary_type?: string;

  @Column({
    type: 'boolean',
    default: false,
  })
  log_quantity?: boolean;

  @Column({
    type: 'numeric',
    nullable: false,
  })
  duration_seconds?: number;

  @Column({
    type: 'varchar',
    default: null,
  })
  completion_requirements?: string;

  @Column({
    type: 'jsonb',
    nullable: false,
    transformer: BaseEntity.encryptJSONField('activity_data'),
  })
  activity_data?: ActivityData;

  @Column({
    type: 'boolean',
    default: false,
  })
  is_default?: boolean;

  @Column({
    type: 'boolean',
    default: false,
  })
  run_micro_breaks?: boolean;

  @Column({
    type: 'jsonb',
  })
  days_of_week?: DaysOfWeek[];

  @Column({
    type: 'jsonb',
    nullable: true,
    transformer: BaseEntity.encryptJSONField('check_list'),
  })
  check_list?: string[];

  @Column({
    type: 'enum',
    name: 'impact_category',
    enum: ImpactCategory,
    nullable: true,
    default: null,
  })
  impact_category?: ImpactCategory;

  @Column({
    type: 'varchar',
  })
  cutoff_time_for_doing_activity?: string;

  @Index()
  @Column({
    type: 'uuid',
    nullable: true,
    default: null,
  })
  geofence_id?: string;

  @Column({
    type: 'boolean',
    default: false,
  })
  is_deleted?: boolean;

  @ManyToOne(() => Geofence, { onDelete: 'SET NULL', onUpdate: 'CASCADE' })
  @JoinColumn({ name: 'geofence_id' })
  geofence?: Geofence;

  @ManyToOne(() => ActivitySequence, (activity_sequence) => activity_sequence.activities, {
    onDelete: 'CASCADE',
    onUpdate: 'CASCADE',
  })
  @JoinColumn({ name: 'activity_sequence_id' })
  activity_sequence?: ActivitySequence;

  @OneToMany(() => CompletedActivity, (completed_activity) => completed_activity.activity, {
    onDelete: 'CASCADE',
    onUpdate: 'NO ACTION',
  })
  completed_activities?: CompletedActivity[];

  @ManyToOne(() => Activity, (activity) => activity.choices, { onDelete: 'CASCADE', onUpdate: 'CASCADE' })
  @JoinColumn({ name: 'parent_id' })
  parent_activity?: ActivitySequence;

  @ManyToOne(() => Activity, (activity) => activity.linked_activities, { onDelete: 'SET NULL', onUpdate: 'CASCADE' })
  @JoinColumn({ name: 'linked_activity_id' })
  linked_activity?: ActivitySequence;

  @OneToMany(() => Activity, (activity) => activity.linked_activity)
  linked_activities?: Activity[];

  @OneToMany(() => Activity, (activity) => activity.parent_activity)
  choices?: Activity[];

  @OneToMany(() => LogQuantityQuestion, (question) => question.activity)
  log_quantity_questions?: LogQuantityQuestion[];

  @OneToOne(() => User, (user) => user.current_activity)
  user?: User;

  @ManyToOne(() => User, (user) => user.activities, { onDelete: 'CASCADE', onUpdate: 'CASCADE' })
  @JoinColumn({ name: 'user_id' })
  user_activities?: User;

  @ManyToOne(() => ActivityTemplate, (activity_template) => activity_template.activities, {
    onDelete: 'SET NULL',
    onUpdate: 'CASCADE',
  })
  @JoinColumn({ name: 'activity_template_id' })
  activity_template?: ActivityTemplate;

  @OneToOne(() => Tutorial, (tutorial) => tutorial.activity)
  tutorial?: Tutorial;
}
